"""Utilities for storing collections of error messages.

.. warning::

    This module is treated as private API.
    Users should not need to use this module directly.
"""

from marshmallow.exceptions import SCHEMA


class ErrorStore:
    def __init__(self):
        #: Dictionary of errors stored during serialization
        self.errors = {}

    def store_error(self, messages, field_name=SCHEMA, index=None):
        # field error  -> store/merge error messages under field name key
        # schema error -> if string or list, store/merge under _schema key
        #              -> if dict, store/merge with other top-level keys
        messages = copy_containers(messages)
        if field_name != SCHEMA or not isinstance(messages, dict):
            messages = {field_name: messages}
        if index is not None:
            messages = {index: messages}
        self.errors = merge_errors(self.errors, messages)


def copy_containers(errors):
    if isinstance(errors, list):
        return [copy_containers(val) for val in errors]
    if isinstance(errors, dict):
        return {key: copy_containers(val) for key, val in errors.items()}
    return errors


def merge_errors(errors1, errors2):  # noqa: PLR0911
    """Deeply merge two error messages.

    The format of ``errors1`` and ``errors2`` matches the ``message``
    parameter of :exc:`marshmallow.exceptions.ValidationError`.
    """
    if not errors1:
        return errors2
    if not errors2:
        return errors1
    if isinstance(errors1, list):
        if isinstance(errors2, list):
            errors1.extend(errors2)
            return errors1
        if isinstance(errors2, dict):
            errors2[SCHEMA] = merge_errors(errors1, errors2.get(SCHEMA))
            return errors2
        errors1.append(errors2)
        return errors1
    if isinstance(errors1, dict):
        if isinstance(errors2, dict):
            for key, val in errors2.items():
                if key in errors1:
                    errors1[key] = merge_errors(errors1[key], val)
                else:
                    errors1[key] = val
            return errors1
        errors1[SCHEMA] = merge_errors(errors1.get(SCHEMA), errors2)
        return errors1
    if isinstance(errors2, list):
        return [errors1, *errors2]
    if isinstance(errors2, dict):
        errors2[SCHEMA] = merge_errors(errors1, errors2.get(SCHEMA))
        return errors2
    return [errors1, errors2]

    def _invoke_schema_validators(
        self,
        *,
        error_store: ErrorStore,
        pass_collection: bool,
        data,
        original_data,
        many: bool,
        partial: bool | types.StrSequenceOrSet | None,
        field_errors: bool = False,
        unknown: types.UnknownOption | None,
    ):
        for attr_name, hook_many, validator_kwargs in self._hooks[VALIDATES_SCHEMA]:
            if hook_many != pass_collection:
                continue
            validator = getattr(self, attr_name)
            if field_errors and validator_kwargs["skip_on_field_errors"]:
                continue
            pass_original = validator_kwargs.get("pass_original", False)

            if many and not pass_collection:
                for idx, (item, orig) in enumerate(
                    zip(data, original_data, strict=True)
                ):
                    self._run_validator(
                        validator,
                        item,
                        original_data=orig,
                        error_store=error_store,
                        many=many,
                        partial=partial,
                        unknown=unknown,
                        index=idx,
                        pass_original=pass_original,
                    )
            else:
                self._run_validator(
                    validator,
                    data,
                    original_data=original_data,
                    error_store=error_store,
                    many=many,
                    pass_original=pass_original,
                    partial=partial,
                    unknown=unknown,
                )

def _deserialize(
    self,
    data: Mapping[str, typing.Any] | Sequence[Mapping[str, typing.Any]],
    *,
    error_store: ErrorStore,
    many: bool = False,
    partial=None,
    unknown: types.UnknownOption = RAISE,
    index=None,
) -> typing.Any | list[typing.Any]:
    """Deserialize ``data``.

    :param data: The data to deserialize.
    :param error_store: Structure to store errors.
    :param many: `True` if ``data`` should be deserialized as a collection.
    :param partial: Whether to ignore missing fields and not require
        any fields declared. Propagates down to ``Nested`` fields as well. If
        its value is an iterable, only missing fields listed in that iterable
        will be ignored. Use dot delimiters to specify nested fields.
    :param unknown: Whether to exclude, include, or raise an error for unknown
        fields in the data. Use `EXCLUDE`, `INCLUDE` or `RAISE`.
    :param index: Index of the item being serialized (for storing errors) if
        serializing a collection, otherwise `None`.
    :return: The deserialized data as `dict_class` instance or list of `dict_class`
    instances if `many` is `True`.
    """
    index = index if self.opts.index_errors else None
    if many:
        if not is_sequence_but_not_string(data):
            error_store.store_error([self.error_messages["type"]], index=index)
            ret_l = []
        else:
            ret_l = [
                self._deserialize(
                    d,
                    error_store=error_store,
                    many=False,
                    partial=partial,
                    unknown=unknown,
                    index=idx,
                )
                for idx, d in enumerate(data)
            ]
        return ret_l
    ret_d = self.dict_class()
    # Check data is a dict
    if not isinstance(data, Mapping):
        error_store.store_error([self.error_messages["type"]], index=index)
    else:
        partial_is_collection = is_collection(partial)
        for attr_name, field_obj in self.load_fields.items():
            field_name = (
                field_obj.data_key if field_obj.data_key is not None else attr_name
            )
            raw_value = data.get(field_name, missing)
            if raw_value is missing:
                # Ignore missing field if we're allowed to.
                if partial is True or (
                    partial_is_collection and attr_name in partial
                ):
                    continue
            d_kwargs = {}
            # Allow partial loading of nested schemas.
            if partial_is_collection:
                prefix = attr_name + "."
                len_prefix = len(prefix)
                sub_partial = [
                    f[len_prefix:] for f in partial if f.startswith(prefix)
                ]
                d_kwargs["partial"] = sub_partial
            elif partial is not None:
                d_kwargs["partial"] = partial

            def getter(
                val, field_obj=field_obj, field_name=field_name, d_kwargs=d_kwargs
            ):
                return field_obj.deserialize(
                    val,
                    field_name,
                    data,
                    **d_kwargs,
                )

            value = self._call_and_store(
                getter_func=getter,
                data=raw_value,
                field_name=field_name,
                error_store=error_store,
                index=index,
            )
            if value is not missing:
                key = field_obj.attribute or attr_name
                set_value(ret_d, key, value)
        if unknown != EXCLUDE:
            fields = {
                field_obj.data_key if field_obj.data_key is not None else field_name
                for field_name, field_obj in self.load_fields.items()
            }
            for key in set(data) - fields:
                value = data[key]
                if unknown == INCLUDE:
                    ret_d[key] = value
                elif unknown == RAISE:
                    error_store.store_error(
                        [self.error_messages["unknown"]],
                        key,
                        index,
                    )
    return ret_d

